import itertools

def cost(x1, x2, x3):
    return -2*x1 - 3*x2 - 4*x3 + 4*x1*x3

xs = list(itertools.product([0, 1], repeat=3))
vals = [cost(*x) for x in xs]
print(min(vals))

def ising(Z):
    return cost((1 - Z[0]) / 2, (1 - Z[1]) / 2, (1 - Z[2]) / 2)

Zs = list(itertools.product([1, -1], repeat=3))

def coef(S):
    total = 0
    for Z in Zs:
        prod = 1
        for i in S:
            prod *= Z[i]
        total += ising(Z) * prod
    return total / len(Zs)

print(coef(()))
print(coef((0,)))
print(coef((1,)))
print(coef((2,)))
print(coef((0, 2)))
print(ising((1, -1, -1)))
